  /**
   * @method
   * @name bitbns#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<ccxt::any>
  fetchStatus(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response =
                            awaitValue(this->v1GetPlatformStatus(params));
                        //
                        //     {
                        //         "data":{
                        //             "BTC":{"status":1},
                        //             "ETH":{"status":1},
                        //             "XRP":{"status":1},
                        //         },
                        //         "status":1,
                        //         "error":null,
                        //         "code":200
                        //     }
                        //
                        ccxt::any statusRaw =
                            this->safeString(response, std::string("status"));
                        return ccxt::dict{
                            {std::string("status"),
                             this->safeString(
                                 ccxt::dict{
                                     {std::string("1"), std::string("ok")},
                                 },
                                 statusRaw, statusRaw)},
                            {std::string("updated"), ccxt::any{}},
                            {std::string("eta"), ccxt::any{}},
                            {std::string("url"), ccxt::any{}},
                            {std::string("info"), response},
                        };
                      })
        .share();
  }

  /**
   * @method
   * @name bitbns#fetchMarkets
   * @description retrieves data on all markets for bitbns
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any response =
                     awaitValue(this->wwwGetOrderFetchMarkets(params));
                 //
                 //     [
                 //         {
                 //             "id":"BTC",
                 //             "symbol":"BTC/INR",
                 //             "base":"BTC",
                 //             "quote":"INR",
                 //             "baseId":"BTC",
                 //             "quoteId":"",
                 //             "active":true,
                 //             "limits":{
                 //                 "amount":{"min":"0.00017376","max":20},
                 //                 "price":{"min":2762353.2359999996,"max":6445490.883999999},
                 //                 "cost":{"min":800,"max":128909817.67999998}
                 //             },
                 //             "precision":{
                 //                 "amount":8,
                 //                 "price":2
                 //             },
                 //             "info":{}
                 //         },
                 //     ]
                 //
                 ccxt::any result = ccxt::list{};
                 ccxt::any rawMarkets = this->toArray(response);
                 for (ccxt::any i = 0;
                      isLessThan(i, getArrayLength(rawMarkets));
                      postFixIncrement(i)) {
                   ccxt::any market = ::getValue(rawMarkets, i);
                   ccxt::any id = this->safeString(market, std::string("id"));
                   ccxt::any baseId =
                       this->safeString(market, std::string("base"));
                   ccxt::any quoteId =
                       this->safeString(market, std::string("quote"));
                   ccxt::any base = this->safeCurrencyCode(baseId);
                   ccxt::any quote = this->safeCurrencyCode(quoteId);
                   ccxt::any marketPrecision = this->safeDict(
                       market, std::string("precision"), ccxt::dict{});
                   ccxt::any marketLimits = this->safeDict(
                       market, std::string("limits"), ccxt::dict{});
                   ccxt::any amountLimits = this->safeDict(
                       marketLimits, std::string("amount"), ccxt::dict{});
                   ccxt::any priceLimits = this->safeDict(
                       marketLimits, std::string("price"), ccxt::dict{});
                   ccxt::any costLimits = this->safeDict(
                       marketLimits, std::string("cost"), ccxt::dict{});
                   ccxt::any usdt = (isEqual(quoteId, std::string("USDT")));
                   // INR markets don't need a _INR prefix
                   ccxt::any uppercaseId =
                       (isTrue(usdt)
                            ? ccxt::any(
                                  (add(add(baseId, std::string("_")), quoteId)))
                            : ccxt::any(baseId));
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), id},
                           {std::string("uppercaseId"), uppercaseId},
                           {std::string("symbol"),
                            add(add(base, std::string("/")), quote)},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), ccxt::any{}},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), ccxt::any{}},
                           {std::string("type"), std::string("spot")},
                           {std::string("spot"), true},
                           {std::string("margin"), false},
                           {std::string("swap"), false},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"),
                            this->safeBool(market, std::string("active"))},
                           {std::string("contract"), false},
                           {std::string("linear"), ccxt::any{}},
                           {std::string("inverse"), ccxt::any{}},
                           {std::string("contractSize"), ccxt::any{}},
                           {std::string("expiry"), ccxt::any{}},
                           {std::string("expiryDatetime"), ccxt::any{}},
                           {std::string("strike"), ccxt::any{}},
                           {std::string("optionType"), ccxt::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->parseNumber(this->parsePrecision(
                                     this->safeString(marketPrecision,
                                                      std::string("amount"))))},
                                {std::string("price"),
                                 this->parseNumber(this->parsePrecision(
                                     this->safeString(marketPrecision,
                                                      std::string("price"))))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), ccxt::any{}},
                                     {std::string("max"), ccxt::any{}},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(amountLimits,
                                                       std::string("min"))},
                                     {std::string("max"),
                                      this->safeNumber(amountLimits,
                                                       std::string("max"))},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(priceLimits,
                                                       std::string("min"))},
                                     {std::string("max"),
                                      this->safeNumber(priceLimits,
                                                       std::string("max"))},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(costLimits,
                                                       std::string("min"))},
                                     {std::string("max"),
                                      this->safeNumber(costLimits,
                                                       std::string("max"))},
                                 }},
                            }},
                           {std::string("created"), ccxt::any{}},
                           {std::string("info"), market},
                       });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name bitbns#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                ccxt::any market = this->market(symbol);
                ccxt::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                };
                if (isTrue(!isEqual(limit, ccxt::any{}))) {
                  ::setValue(
                      request, std::string("limit"),
                      limit); // default 100, max 5000, see
                              // https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#order-book
                }
                ccxt::any response = awaitValue(this->wwwGetOrderFetchOrderbook(
                    this->extend(request, params)));
                //
                //     {
                //         "bids":[
                //             [49352.04,0.843948],
                //             [49352.03,0.742048],
                //             [49349.78,0.686239],
                //         ],
                //         "asks":[
                //             [49443.59,0.065137],
                //             [49444.63,0.098211],
                //             [49449.01,0.066309],
                //         ],
                //         "timestamp":1619172786577,
                //         "datetime":"2021-04-23T10:13:06.577Z",
                //         "nonce":""
                //     }
                //
                ccxt::any timestamp =
                    this->safeInteger(response, std::string("timestamp"));
                return this->parseOrderBook(
                    response, ::getValue(market, std::string("symbol")),
                    timestamp);
              })
            .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "symbol":"BTC/INR",
    //         "info":{
    //             "highest_buy_bid":4368494.31,
    //             "lowest_sell_bid":4374835.09,
    //             "last_traded_price":4374835.09,
    //             "yes_price":4531016.27,
    //             "volume":{"max":"4569119.23","min":"4254552.13","volume":62.17722344}
    //         },
    //         "timestamp":1619100020845,
    //         "datetime":1619100020845,
    //         "high":"4569119.23",
    //         "low":"4254552.13",
    //         "bid":4368494.31,
    //         "bidVolume":"",
    //         "ask":4374835.09,
    //         "askVolume":"",
    //         "vwap":"",
    //         "open":4531016.27,
    //         "close":4374835.09,
    //         "last":4374835.09,
    //         "baseVolume":62.17722344,
    //         "quoteVolume":"",
    //         "previousClose":"",
    //         "change":-156181.1799999997,
    //         "percentage":-3.446934874943623,
    //         "average":4452925.68
    //     }
    //
    ccxt::any timestamp = this->safeInteger(ticker, std::string("timestamp"));
    ccxt::any marketId = this->safeString(ticker, std::string("symbol"));
    ccxt::any symbol = this->safeSymbol(marketId, market);
    ccxt::any last = this->safeString(ticker, std::string("last"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString(ticker, std::string("high"))},
            {std::string("low"), this->safeString(ticker, std::string("low"))},
            {std::string("bid"), this->safeString(ticker, std::string("bid"))},
            {std::string("bidVolume"),
             this->safeString(ticker, std::string("bidVolume"))},
            {std::string("ask"), this->safeString(ticker, std::string("ask"))},
            {std::string("askVolume"),
             this->safeString(ticker, std::string("askVolume"))},
            {std::string("vwap"),
             this->safeString(ticker, std::string("vwap"))},
            {std::string("open"),
             this->safeString(ticker, std::string("open"))},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"),
             this->safeString(ticker, std::string("previousClose"))},
            {std::string("change"),
             this->safeString(ticker, std::string("change"))},
            {std::string("percentage"),
             this->safeString(ticker, std::string("percentage"))},
            {std::string("average"),
             this->safeString(ticker, std::string("average"))},
            {std::string("baseVolume"),
             this->safeString(ticker, std::string("baseVolume"))},
            {std::string("quoteVolume"),
             this->safeString(ticker, std::string("quoteVolume"))},
            {std::string("info"), ticker},
        },
        market);
  }

